import json, numpy as np
from scipy.optimize import minimize

runs = json.load(open('/app/my_lab_history.json'))
valid = [r for r in runs if not r['result']['diverged'] and r['result']['final_loss']]

data = {}
for r in valid:
    key = (r['args']['n'], r['args']['steps'], r['args']['eta'])
    if key not in data:
        data[key] = []
    data[key].append(r['result']['final_loss'])

# Let's only use configs where loss < 8.0 (excluding runaway loss spikes like 1005.59 or 9.002)
clean_pts = []
for (n, s, eta), losses in data.items():
    m = np.mean(losses)
    if m < 7.5:
        clean_pts.append((n, s, eta, m))

print(f'Clean points: {len(clean_pts)}')

# Let's inspect a few points
for p in clean_pts[:10]:
    print(p)
